                                    pat: local.pat.clone(),
                                    init: Some(syn_verus::LocalInit {
                                        eq_token: i.eq_token.clone(),
                                        expr: Box::new(i_expr),
                                        diverge: i.diverge.clone().map_or_else(
                                            || None,
